CREATE EXTENSION IF NOT EXISTS vector;

CREATE TYPE "DeploymentMode" AS ENUM ('ON_PREMISE', 'PRIVATE_CLOUD', 'HYBRID', 'MANAGED_SAAS');
CREATE TYPE "AuditEventType" AS ENUM ('AUTH', 'ADMIN_CONFIG', 'CONNECTOR_OPERATION', 'SQL_GENERATION', 'SQL_EXECUTION', 'RAG_INGESTION', 'RAG_RETRIEVAL', 'LLM_CALL', 'AGENT_RUN', 'TOOL_EXECUTION', 'WORKFLOW_ACTION', 'APPROVAL_DECISION', 'SAFETY_GATE', 'EXTERNAL_INGESTION', 'SIMULATION_RUN');
CREATE TYPE "SafetyGateStatus" AS ENUM ('PASS', 'WARNING', 'BLOCKED');
CREATE TYPE "ApprovalStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED');
CREATE TYPE "JobStatusValue" AS ENUM ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED');
CREATE TYPE "AlertPriority" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL');

CREATE TABLE "Tenant" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "deploymentMode" "DeploymentMode" NOT NULL DEFAULT 'ON_PREMISE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TenantConfig" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL UNIQUE REFERENCES "Tenant"("id") ON DELETE CASCADE, "productName" TEXT NOT NULL, "locale" TEXT NOT NULL DEFAULT 'tr-TR', "customDomain" TEXT, "enabledFeatures" JSONB NOT NULL, "industryDomainPack" TEXT NOT NULL, "modelPolicy" JSONB NOT NULL, "dataResidencyPolicy" JSONB NOT NULL, "securityPolicy" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BrandConfig" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL UNIQUE REFERENCES "Tenant"("id") ON DELETE CASCADE, "productName" TEXT NOT NULL, "logoUrl" TEXT, "primaryColor" TEXT NOT NULL, "secondaryColor" TEXT NOT NULL, "accentColor" TEXT NOT NULL, "textColor" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FeatureFlag" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "key" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT false, "config" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","key"));
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "email" TEXT NOT NULL, "displayName" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "authType" TEXT NOT NULL DEFAULT 'local', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","email"));
CREATE TABLE "Role" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Permission" ("id" TEXT PRIMARY KEY, "key" TEXT NOT NULL UNIQUE, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UserRole" ("userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "roleId" TEXT NOT NULL REFERENCES "Role"("id") ON DELETE CASCADE, PRIMARY KEY ("userId","roleId"));
CREATE TABLE "RolePermission" ("roleId" TEXT NOT NULL REFERENCES "Role"("id") ON DELETE CASCADE, "permissionId" TEXT NOT NULL REFERENCES "Permission"("id") ON DELETE CASCADE, PRIMARY KEY ("roleId","permissionId"));
CREATE TABLE "SecretReference" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "provider" TEXT NOT NULL, "reference" TEXT NOT NULL, "purpose" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Connector" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "type" TEXT NOT NULL, "name" TEXT NOT NULL, "config" JSONB NOT NULL, "secretReferenceId" TEXT, "status" TEXT NOT NULL DEFAULT 'unknown', "allowedTables" JSONB, "allowedColumns" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "BusinessGlossaryTerm" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "term" TEXT NOT NULL, "definition" TEXT NOT NULL, "synonyms" JSONB NOT NULL, "locale" TEXT NOT NULL DEFAULT 'tr-TR', "domain" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","term"));
CREATE TABLE "MetricDefinition" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "formula" TEXT NOT NULL, "sqlMappingHints" JSONB NOT NULL, "tableMapping" JSONB NOT NULL, "columnMapping" JSONB NOT NULL, "synonyms" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","key"));
CREATE TABLE "QueryTrace" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "userId" TEXT NOT NULL, "question" TEXT NOT NULL, "language" TEXT NOT NULL, "generatedSql" TEXT, "safetyStatus" "SafetyGateStatus" NOT NULL, "confidenceScore" DOUBLE PRECISION, "resultSummary" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Document" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "title" TEXT NOT NULL, "sourceType" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DocumentChunk" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "documentId" TEXT NOT NULL REFERENCES "Document"("id") ON DELETE CASCADE, "content" TEXT NOT NULL, "chunkIndex" INTEGER NOT NULL, "embedding" vector, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "VectorIndex" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "provider" TEXT NOT NULL DEFAULT 'pgvector', "freshnessAt" TIMESTAMP(3), "documentCount" INTEGER NOT NULL DEFAULT 0, "chunkCount" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Prompt" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","key"));
CREATE TABLE "PromptVersion" ("id" TEXT PRIMARY KEY, "promptId" TEXT NOT NULL REFERENCES "Prompt"("id") ON DELETE CASCADE, "version" INTEGER NOT NULL, "body" TEXT NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("promptId","version"));
CREATE TABLE "PromptExecutionTrace" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "promptKey" TEXT NOT NULL, "promptVersion" INTEGER NOT NULL, "model" TEXT NOT NULL, "input" JSONB NOT NULL, "output" JSONB, "status" TEXT NOT NULL, "tokenUsage" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ModelUsage" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "provider" TEXT NOT NULL, "model" TEXT NOT NULL, "inputTokens" INTEGER NOT NULL DEFAULT 0, "outputTokens" INTEGER NOT NULL DEFAULT 0, "operation" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AgentTemplate" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "defaultTools" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Agent" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "templateId" TEXT, "instructions" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Tool" ("id" TEXT PRIMARY KEY, "key" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "riskLevel" TEXT NOT NULL, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ToolPermission" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "roleId" TEXT NOT NULL, "toolKey" TEXT NOT NULL, "allowed" BOOLEAN NOT NULL DEFAULT false, "requiresApproval" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","roleId","toolKey"));
CREATE TABLE "AgentExecutionTrace" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "userId" TEXT NOT NULL, "agentId" TEXT NOT NULL, "input" JSONB NOT NULL, "output" JSONB, "toolCalls" JSONB, "safetyStatus" "SafetyGateStatus" NOT NULL, "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Workflow" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "steps" JSONB NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Action" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "workflowId" TEXT, "type" TEXT NOT NULL, "payload" JSONB NOT NULL, "riskLevel" TEXT NOT NULL, "status" TEXT NOT NULL, "rollbackPlan" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ApprovalRequest" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "requestedBy" TEXT NOT NULL, "actionType" TEXT NOT NULL, "subjectId" TEXT NOT NULL, "reason" TEXT NOT NULL, "status" "ApprovalStatus" NOT NULL DEFAULT 'PENDING', "decidedBy" TEXT, "decisionNote" TEXT, "decidedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MetricSubscription" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "metricKey" TEXT NOT NULL, "subscriberUserId" TEXT NOT NULL, "schedule" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AlertRule" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "metricKey" TEXT NOT NULL, "ruleType" TEXT NOT NULL, "threshold" DOUBLE PRECISION, "sensitivity" DOUBLE PRECISION, "priority" "AlertPriority" NOT NULL DEFAULT 'MEDIUM', "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "AlertEvent" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "ruleId" TEXT NOT NULL, "priority" "AlertPriority" NOT NULL, "title" TEXT NOT NULL, "explanation" TEXT NOT NULL, "dedupeKey" TEXT NOT NULL, "acknowledgedAt" TIMESTAMP(3), "acknowledgedBy" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","dedupeKey"));
CREATE TABLE "ExternalSource" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "url" TEXT, "governanceApproved" BOOLEAN NOT NULL DEFAULT false, "rateLimitPerHour" INTEGER NOT NULL DEFAULT 60, "confidenceScore" DOUBLE PRECISION NOT NULL DEFAULT 0.5, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "ExternalIngestionJob" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "sourceId" TEXT NOT NULL, "status" "JobStatusValue" NOT NULL, "normalizedCount" INTEGER NOT NULL DEFAULT 0, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3));
CREATE TABLE "SimulationScenario" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "parameters" JSONB NOT NULL, "requiresApprovalForAction" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "Segment" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "definition" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "SyntheticUserSegment" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "name" TEXT NOT NULL, "size" INTEGER NOT NULL, "attributes" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("tenantId","name"));
CREATE TABLE "SimulationResult" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "scenarioId" TEXT NOT NULL, "input" JSONB NOT NULL, "output" JSONB NOT NULL, "safetyStatus" "SafetyGateStatus" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SafetyGateCheck" ("id" TEXT PRIMARY KEY, "key" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "severity" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SafetyGateRun" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "checkKey" TEXT NOT NULL, "operationType" TEXT NOT NULL, "operationId" TEXT, "status" "SafetyGateStatus" NOT NULL, "message" TEXT NOT NULL, "details" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE, "actorUserId" TEXT, "eventType" "AuditEventType" NOT NULL, "action" TEXT NOT NULL, "resourceType" TEXT NOT NULL, "resourceId" TEXT, "correlationId" TEXT NOT NULL, "ipAddress" TEXT, "userAgent" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ComplianceEvidence" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "controlKey" TEXT NOT NULL, "title" TEXT NOT NULL, "evidence" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "JobStatus" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "type" TEXT NOT NULL, "status" "JobStatusValue" NOT NULL, "progress" INTEGER NOT NULL DEFAULT 0, "message" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX "AuditLog_tenantId_createdAt_idx" ON "AuditLog"("tenantId", "createdAt");
CREATE INDEX "SafetyGateRun_tenantId_createdAt_idx" ON "SafetyGateRun"("tenantId", "createdAt");
CREATE INDEX "QueryTrace_tenantId_createdAt_idx" ON "QueryTrace"("tenantId", "createdAt");
CREATE INDEX "AgentExecutionTrace_tenantId_createdAt_idx" ON "AgentExecutionTrace"("tenantId", "createdAt");
CREATE INDEX "AlertEvent_tenantId_createdAt_idx" ON "AlertEvent"("tenantId", "createdAt");
CREATE INDEX "SimulationResult_tenantId_createdAt_idx" ON "SimulationResult"("tenantId", "createdAt");
